"""Auto-generated reranking experiment report (Rule 9)."""

from __future__ import annotations

from collections.abc import Sequence
from datetime import datetime, timezone

from app.evaluation.reranking_benchmark import RERANK_CANDIDATES, RERANK_TOP_N, RerankBenchmarkResult


def render_reranking_report(
    results: Sequence[RerankBenchmarkResult],
    *,
    n_samples: int,
    reranker_key: str,
) -> str:
    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines: list[str] = []
    lines.append("# Reranking Experiments (Phase 9)")
    lines.append("")
    lines.append(f"> Auto-generated by `scripts/run_reranking_benchmark.py` on {now}.")
    lines.append(f"> {n_samples} questions · reranker: `{reranker_key}` · pipeline: top-{RERANK_CANDIDATES} → rerank → top-{RERANK_TOP_N}")
    lines.append("")
    lines.append("## Methodology")
    lines.append("")
    lines.append("- Base retriever: hybrid RRF (dense hash embeddings + pure BM25) — same harness as Phases 5/8.")
    lines.append("- Gold evidence spans unchanged; metrics recomputed on the reranked top-K.")
    lines.append("- The CI reranker is the deterministic hash double: this report measures **pipeline mechanics")
    lines.append("  and latency accounting**. Real cross-encoder quality deltas land in Phase 21 (D-052).")
    lines.append("")
    lines.append("## Results")
    lines.append("")
    lines.append("| Configuration | MRR | Recall@5 | Recall@10 | Precision@5 | mean total (ms) | p95 total (ms) | mean rerank (ms) | pairs scored |")
    lines.append("|---|---|---|---|---|---|---|---|---|")
    for r in results:
        lines.append(
            f"| {r.name} "
            f"| {r.metrics.get('mrr', 0):.4f} "
            f"| {r.metrics.get('recall_at_5', 0):.4f} "
            f"| {r.metrics.get('recall_at_10', 0):.4f} "
            f"| {r.metrics.get('precision_at_5', 0):.4f} "
            f"| {r.latency_stats.get('mean_total_ms', 0):.1f} "
            f"| {r.latency_stats.get('p95_total_ms', 0):.1f} "
            f"| {r.latency_stats.get('mean_rerank_ms', 0):.2f} "
            f"| {r.pairs_scored} |"
        )
    lines.append("")
    lines.append("## Trade-off (ADR-004)")
    lines.append("")
    lines.append("Reranking spends one cross-encoder pass per candidate pair. The budget question is:")
    lines.append("*does the MRR/Recall gain justify the rerank latency at our candidate count?*")
    lines.append("- Candidate count (50 in production) and keep count (10) are config, not constants —")
    lines.append("  they are experimental variables in Phase 21.")
    lines.append("- The reranker stays in the default path only while measured gains justify measured latency.")
    lines.append("- Failure behavior: a dead reranker degrades to the unreranked ordering (D-049) —")
    lines.append("  retrieval quality never drops to zero because scoring failed.")
    lines.append("")
    return "\n".join(lines)